let settingsBusy=false;
function seasonFormatSetting(){return state.scheduleFormat==='custom'?'custom':state.scheduleFormat==='nba82'?82:[1,2,4].includes(state.meetings)?state.meetings:2}
function seasonSettingsLocked(){return state.teams.some(t=>t.w+t.l>0)||state.history.some(g=>g.stage==='Regular season')}
function settingsView(){const locked=seasonSettingsLocked();return `<section class="panel"><div class="panelhead"><h2>Game settings</h2></div><form class="note" onsubmit="saveGameSettings(event)"><div class="tm-grid"><label>League name<input name="leagueName" maxlength="60" value="${escapeHTML(state.leagueName||'Dynasty Basketball League')}" required></label><label>General manager name<input name="gmName" maxlength="40" value="${escapeHTML(state.gmName||'General Manager')}" required></label><label>Appearance<select name="theme"><option value="dark" ${state.darkMode?'selected':''}>Dark</option><option value="light" ${!state.darkMode?'selected':''}>Light</option></select></label><label>Future player generation<select name="gender">${genderOptions(state.leagueGender||'male')}</select></label></div><p class="muted">Player gender applies to future recruits. Existing players retain their names, attributes, and biographies.</p><h3>Season rules ${locked?'· Locked':'· Preseason'}</h3><p>${locked?'The first regular-season game has been played. Salary cap and schedule format are locked until next preseason.':'Set the salary cap and schedule before the first regular-season game. Changing the format rebuilds the unplayed calendar.'}</p><fieldset class="settings-season" ${locked?'disabled':''}><div class="tm-grid"><label>Schedule format<select name="format"><option value="custom" ${state.scheduleFormat==='custom'?'selected':''}>Custom · Schedule settings below</option><option value="82" ${state.scheduleFormat==='nba82'?'selected':''} ${nbaAlignment(state.teams)?'':'disabled'}>82 games · Standard 30-team alignment</option>${[1,2,4].map(n=>`<option value="${n}" ${state.scheduleFormat!=='nba82'&&seasonFormatSetting()===n?'selected':''} ${n===4&&state.teams.length>30?'disabled':''}>${n} game${n>1?'s':''} per opponent · Round robin</option>`).join('')}</select></label></div></fieldset><p class="muted">League names, manager names, appearance, and future player generation remain editable throughout the season.</p><p id="settings-error" role="alert"></p><div class="actions"><button type="button" onclick="render()" ${settingsBusy?'disabled':''}>Reset changes</button><button class="primary" ${settingsBusy?'disabled':''}>Save settings</button></div></form></section>`}
async function saveGameSettings(event){event.preventDefault();if(settingsBusy||!ownerCanManage())return;const v=Object.fromEntries(new FormData(event.target)),before=snapshotState();settingsBusy=true;try{
 const leagueName=String(v.leagueName||'').trim(),gmName=String(v.gmName||'').trim();if(!leagueName||leagueName.length>60||!gmName||gmName.length>40||!['dark','light'].includes(v.theme)||!LEAGUE_GENDERS.includes(v.gender))throw Error('Enter valid names, appearance, and player generation settings.');
 const priorStamp=medicalStamp(),previous={...leagueRules()},rules=readLeagueSettingsForm(v),locked=seasonSettingsLocked(),currentFormat=seasonFormatSetting(),submitted=v.format===undefined?currentFormat:v.format==='custom'?'custom':Number(v.format),changed=CUSTOM_SCHEDULE_KEYS.some(k=>rules[k]!==previous[k]),eventsChanged=['allStarEnabled','allStarSchedule','allStarPercent','allStarEventDays','allStarRestLength','restDistribution','openingNightFormat','openingWindowDays'].some(k=>rules[k]!==previous[k]);
 const format=changed?'custom':submitted,cap=v.cap===undefined?salaryCap():Number(v.cap);if(locked&&(cap!==salaryCap()||format!==currentFormat))throw Error('Season rules are locked after the first regular-season game.');
 if(!Number.isFinite(cap)||cap<.000001||cap>1000||![1,2,4,82,'custom'].includes(format))throw Error('Choose a valid salary cap and schedule format.');
 validatePlayoffRules(rules,state.teams);
 if(!locked){let calendar=null;if(format===82&&!nbaAlignment(state.teams))throw Error('82 games requires the standard 30-team conference/division alignment.');if(format===4&&state.teams.length>30)throw Error('Expanded leagues support one or two games per opponent.');
  if(changed||eventsChanged||format!==currentFormat){calendar=format==='custom'?customSeasonSchedule(state.teams,state.year,rules):format===82?nbaSeasonSchedule(state.teams,state.year):schedule(format,state.teams.length);state.schedule=calendar;state.scheduleFormat=format==='custom'?'custom':format===82?'nba82':'roundRobin';state.meetings=format==='custom'?rules.seasonGames:format;state.day=0;delete state.scheduleAlignment;delete state.powerMovement;if(format==='custom')state.customScheduleAlignment=managementAlignment(state.teams);else{delete state.customScheduleAlignment;Object.assign(rules,calendarSettingDefaults(state))}}
  if(calendar){delete state.allStarCalendar;delete state.allStarEvents;delete state.allStarVoting;state.allStarReport=[];applyAllStarCalendar(state,rules);}state.salaryCap=cap;if(calendar||cap!==before.salaryCap)for(const t of state.teams){if(t.owner)t.owner.plan=ownerNewPlan(t);if(state.finances?.[t.id])state.finances[t.id].season.lastDay=state.day}
 }
 Object.assign(state,{leagueName,gmName,darkMode:v.theme==='dark',leagueGender:v.gender,leagueSettings:rules});const calendarShift=medicalStamp()-priorStamp;if(calendarShift)for(const p of [...state.free,...state.teams.flatMap(t=>t.roster)])if(p.medicalInfo){p.medicalInfo.until+=calendarShift;p.medicalInfo.rehabUntil+=calendarShift}scheduleUI=null;standingsGrouping=rules.standingsGrouping;if(await save()===false)throw Error('Settings could not be saved. Please try again.');settingsBusy=false;render();toast('Settings saved.');
 }catch(e){state=before;const error=document.getElementById('settings-error');if(error)error.textContent=e.message;else toast(e.message)}finally{settingsBusy=false}
}
